extends Node

const SETTINGS_FILE := "user://settings.json"

var master_volume: float = 1.0
var sfx_volume: float = 1.0
var music_volume: float = 1.0
var current_language: String = "it"


func _ready() -> void:
	load_settings()


func set_language(lang: String) -> void:
	current_language = lang
	TranslationServer.set_locale(lang)
	save_settings()


func get_language() -> String:
	return current_language


func save_settings() -> void:
	var data := {
		"master_volume": master_volume,
		"sfx_volume": sfx_volume,
		"music_volume": music_volume,
		"language": current_language
	}
	var file := FileAccess.open(SETTINGS_FILE, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(data))
		file.close()


func load_settings() -> void:
	if not FileAccess.file_exists(SETTINGS_FILE):
		return
	var file := FileAccess.open(SETTINGS_FILE, FileAccess.READ)
	if not file:
		return
	var json := JSON.new()
	if json.parse(file.get_as_text()) == OK:
		var data: Dictionary = json.data
		master_volume = float(data.get("master_volume", 1.0))
		sfx_volume = float(data.get("sfx_volume", 1.0))
		music_volume = float(data.get("music_volume", 1.0))
		current_language = String(data.get("language", "it"))
		TranslationServer.set_locale(current_language)
	file.close()

extends Node

const UNLOCKS_FILE := "user://unlocks.json"

var unlocked_gallery: Array[String] = []
var unlocked_endings: Array[String] = []


func _ready() -> void:
	load_unlocks()


func is_unlocked(id: String) -> bool:
	return unlocked_gallery.has(id) or unlocked_endings.has(id)


func unlock(id: String) -> void:
	if not is_unlocked(id):
		unlocked_endings.append(id)
		save_unlocks()


func save_unlocks() -> void:
	var data := {
		"gallery": unlocked_gallery,
		"endings": unlocked_endings
	}
	var file := FileAccess.open(UNLOCKS_FILE, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(data))
		file.close()


func load_unlocks() -> void:
	if not FileAccess.file_exists(UNLOCKS_FILE):
		return
	var file := FileAccess.open(UNLOCKS_FILE, FileAccess.READ)
	if not file:
		return
	var json := JSON.new()
	if json.parse(file.get_as_text()) == OK:
		var data: Dictionary = json.data
		unlocked_gallery = Array(data.get("gallery", []), TYPE_STRING, "", null)
		unlocked_endings = Array(data.get("endings", []), TYPE_STRING, "", null)
	file.close()

class_name TitleScreen
extends Control

@onready var start_button: Button = $VBoxContainer/StartButton
@onready var language_button: Button = $VBoxContainer/LanguageButton
@onready var quit_button: Button = $VBoxContainer/QuitButton


func _ready() -> void:
	if start_button:
		start_button.pressed.connect(_on_start_pressed)
	if language_button:
		language_button.pressed.connect(_on_language_pressed)
		_update_language_text()
	if quit_button:
		quit_button.pressed.connect(_on_quit_pressed)


func _on_start_pressed() -> void:
	SceneManager.change_scene_to_file("res://story/story_screen.tscn")


func _on_language_pressed() -> void:
	var current := SettingsManager.get_language()
	var new_lang := "en" if current == "it" else "it"
	SettingsManager.set_language(new_lang)
	_update_language_text()


func _update_language_text() -> void:
	if language_button:
		var current := SettingsManager.get_language()
		language_button.text = "Language: EN" if current == "en" else "Lingua: IT"


func _on_quit_pressed() -> void:
	get_tree().quit()
